def coveringPairs(vals):
    freq = [0] * 256
    for v in vals:
        freq[v] += 1
    total = 0
    for a in range(256):
        if freq[a] == 0:
            continue
        for b in range(a, 256):
            if freq[b] == 0 or (a | b) != 255:
                continue
            if a == b:
                total += freq[a] * (freq[a] - 1) // 2
            else:
                total += freq[a] * freq[b]
    return total
